import os
os.environ.setdefault("PYTORCH_ENABLE_MPS_FALLBACK", "1")

import cv2
import numpy as np

try:
    import torch
except Exception:
    torch = None


def select_torch_device(preference="auto"):
    preference = str(preference or "auto").lower()
    if torch is not None:
        if preference in {"cuda", "auto"}:
            try:
                if torch.cuda.is_available():
                    return "cuda"
            except Exception:
                pass
        if preference in {"mps", "auto"}:
            try:
                if torch.backends.mps.is_available():
                    return "mps"
            except Exception:
                pass
    return "cpu"


def ros_image_to_bgr(img):
    data = img.get("data") or []
    fmt = str(img.get("format") or "").lower()
    if fmt or not img.get("height"):
        arr = np.frombuffer(data, dtype=np.uint8)
        if arr.size <= 0:
            return None
        return cv2.imdecode(arr, cv2.IMREAD_COLOR)
    h = int(img.get("height") or 0)
    w = int(img.get("width") or 0)
    enc = str(img.get("encoding") or "rgb8").lower()
    if h <= 0 or w <= 0:
        return None
    channels = 1 if enc == "mono8" else (4 if enc in {"rgba8", "bgra8"} else 3)
    arr = np.frombuffer(data, dtype=np.uint8)
    needed = h * w * channels
    if arr.size < needed:
        return None
    arr = arr[:needed].reshape((h, w, channels))
    if enc == "rgb8":
        return cv2.cvtColor(arr, cv2.COLOR_RGB2BGR)
    if enc == "rgba8":
        return cv2.cvtColor(arr, cv2.COLOR_RGBA2BGR)
    if enc == "bgra8":
        return cv2.cvtColor(arr, cv2.COLOR_BGRA2BGR)
    if enc == "mono8":
        return cv2.cvtColor(arr, cv2.COLOR_GRAY2BGR)
    return arr if arr.flags["C_CONTIGUOUS"] else np.ascontiguousarray(arr)


def bgr_to_ros_image(bgr):
    if bgr is None:
        return None
    if len(bgr.shape) == 2:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_GRAY2RGB)
    else:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    rgb = np.ascontiguousarray(rgb, dtype=np.uint8)
    h, w = rgb.shape[:2]
    return {
        "height": int(h),
        "width": int(w),
        "encoding": "rgb8",
        "is_bigendian": 0,
        "step": int(w * 3),
        "data": rgb.tobytes(),
    }

from ultralytics import YOLO

DRIVING_CLASS_NAMES = (
    "person", "bicycle", "car", "motorcycle", "bus", "truck", "traffic light", "stop sign",
)


def yolo_model_and_classes(state, weights, filter_classes=True):
    model_key = "model:" + str(weights)
    class_key = "classes:" + str(weights)
    model = state.get(model_key)
    if model is None:
        model = YOLO(weights)
        state[model_key] = model
        class_ids = []
        if filter_classes:
            try:
                for class_id, class_name in model.names.items():
                    if str(class_name) in DRIVING_CLASS_NAMES:
                        class_ids.append(int(class_id))
            except Exception:
                class_ids = []
        state[class_key] = class_ids
    return model, state.get(class_key) or []


def yolo_overlay(state, img, params):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    weights = params.get("weights") or "yolov8n.pt"
    conf = float(params.get("conf", 0.25) or 0.25)
    imgsz = int(params.get("imgsz", 640) or 640)
    filter_classes = bool(params.get("filterDrivingClasses", True))
    preference = params.get("devicePreference") or "auto"
    device_key = "device:" + str(preference)
    device = state.get(device_key)
    if not device:
        device = select_torch_device(preference)
        state[device_key] = device
    if not state.get("device_logged"):
        state["device_logged"] = True
        print("Ultralytics device:", device)
    model, class_ids = yolo_model_and_classes(state, weights, filter_classes)
    options = {"imgsz": imgsz, "conf": conf, "device": device, "verbose": False}
    if class_ids:
        options["classes"] = class_ids
    results = model.predict(bgr, **options)
    if not results:
        return bgr_to_ros_image(bgr)
    return bgr_to_ros_image(results[0].plot())

